118: function findDefaultSpawn(zone, spawnWarpIndex = null) {
119:   if (spawnWarpIndex !== null && zone.warps[spawnWarpIndex]) {
120:     const w = zone.warps[spawnWarpIndex];
121:     const ts = engine.tilesetsByConst[zone.tileset];
122:     const tileAtWarp = engine.getCollisionTileAtStep(zone, w.x, w.y);
123:     // If emerging onto an outdoor door tile, step 1 tile down if passable
124:     if (
125:       zone.romId < 0x25 &&
126:       ts.doorSet.has(tileAtWarp) &&
127:       w.y + 1 < zone.height * 2
128:     ) {
129:       return { x: w.x, y: w.y + 1, dir: "DOWN" };
130:     }
131:     return { x: w.x, y: w.y, dir: "DOWN" };
132:   }
133: 
134:   // For Pallet Town default spawn right between Red's House and Oak's Lab
135:   if (zone.constName === "PALLET_TOWN") {
136:     return { x: 5, y: 6, dir: "DOWN" };
137:   }
138: 
139:   // If the zone has warps, spawn near the first warp or center
140:   if (zone.warps.length > 0) {
141:     const w = zone.warps[0];
142:     if (zone.romId < 0x25 && w.y + 1 < zone.height * 2) {
143:       return { x: w.x, y: w.y + 1, dir: "DOWN" };
144:     }
145:     if (w.y > 0 && engine.isStepPassable(zone, w.x, w.y, w.x, w.y - 1)) {
146:       return { x: w.x, y: w.y - 1, dir: "UP" };
147:     }
148:     return { x: w.x, y: w.y, dir: "DOWN" };
149:   }
150: 
151:   // Otherwise find nearest passable tile to center
152:   const cx = Math.floor(zone.width);
153:   const cy = Math.floor(zone.height);
154:   const ts = engine.tilesetsByConst[zone.tileset];
155:   for (let r = 0; r < Math.max(zone.width, zone.height) * 2; r++) {
156:     for (let dy = -r; dy <= r; dy++) {
157:       for (let dx = -r; dx <= r; dx++) {
158:         const sx = cx + dx;
159:         const sy = cy + dy;
160:         if (sx >= 0 && sx < zone.width * 2 && sy >= 0 && sy < zone.height * 2) {
161:           const tid = engine.getCollisionTileAtStep(zone, sx, sy);
162:           if (ts.passableSet.has(tid)) {
163:             return { x: sx, y: sy, dir: "DOWN" };
164:           }
165:         }
166:       }
167:     }
168:   }
169:   return { x: cx, y: cy, dir: "DOWN" };
170: }
