192: export function loadZone(target, options = {}) {
193:   let zone = null;
194:   if (typeof target === "object" && target !== null) {
195:     zone = target;
196:   } else if (typeof target === "number") {
197:     zone = engine.zonesByNumber[target] || engine.zonesByRomId[target];
198:   } else if (typeof target === "string") {
199:     const clean = target.trim();
200:     if (clean.startsWith("0x") || clean.startsWith("0X")) {
201:       zone = engine.zonesByRomId[parseInt(clean, 16)];
202:     } else if (/^\d+$/.test(clean)) {
203:       zone = engine.zonesByNumber[parseInt(clean, 10)];
204:     } else {
205:       zone =
206:         engine.zonesByConst[clean.toUpperCase()] ||
207:         engine.allZones.find(
208:           (z) =>
209:             z.headerName.toLowerCase() === clean.toLowerCase() ||
210:             z.displayName.toLowerCase() === clean.toLowerCase()
211:         );
212:     }
213:   }
214:   if (!zone) return null;
215: 
216:   // Record outdoor map for LAST_MAP indoor exit warps
217:   if (state.currentZone && state.currentZone.romId < 0x25) {
218:     state.lastOutdoorMap = {
219:       mapConst: state.currentZone.constName,
220:       warpIndex: options.fromOutdoorWarpIndex ?? 0,
221:     };
222:   } else if (zone.romId >= 0x25 && zone.defaultParent) {
223:     if (!state.lastOutdoorMap || options.resetParent) {
224:       state.lastOutdoorMap = { ...zone.defaultParent };
225:     }
226:   }
227: 
228:   state.currentZone = zone;
229:   state.visitedZones.add(zone.constName);
230:   state.npcs = initZoneNpcs(zone);
231:   state.dialogue = null;
232: 
233:   const spawn =
234:     options.x !== undefined && options.y !== undefined
235:       ? { x: options.x, y: options.y, dir: options.dir || state.player.dir }
236:       : findDefaultSpawn(zone, options.warpIndex ?? null);
237: 
238:   state.player.x = spawn.x;
239:   state.player.y = spawn.y;
240:   state.player.renderX = spawn.x;
241:   state.player.renderY = spawn.y;
242:   state.player.dir = spawn.dir || "DOWN";
243:   state.player.walking = false;
244:   state.player.moveAnim = null;
245:   if (zone.romId >= 0x25 && state.player.mode === "bike") {
246:     state.player.mode = "walk";
247:   }
248: 
249:   // Place Pikachu 1 step behind Red
250:   const behindOffsets = {
251:     DOWN: [0, -1],
252:     UP: [0, 1],
253:     LEFT: [1, 0],
254:     RIGHT: [-1, 0],
255:   };
256:   const [bx, by] = behindOffsets[state.player.dir] || [0, -1];
257:   const px = Math.max(0, Math.min(zone.width * 2 - 1, spawn.x + bx));
258:   const py = Math.max(0, Math.min(zone.height * 2 - 1, spawn.y + by));
259:   state.pikachu.x = px;
260:   state.pikachu.y = py;
261:   state.pikachu.renderX = px;
262:   state.pikachu.renderY = py;
263:   state.pikachu.dir = state.player.dir;
264:   state.pikachu.walking = false;
265:   state.pikachu.moveAnim = null;
266: 
267:   audio.playTrack(zone.music);
268:   updateUIForCurrentZone();
269:   renderAllCanvases();
270:   return zone;
271: }
