281: function resolveWarpDestination(zone, warp) {
282:   let destConst = warp.destConst;
283:   let destWarpIdx = warp.destWarpIndex;
284:   if (destConst === "LAST_MAP") {
285:     if (
286:       state.lastOutdoorMap &&
287:       engine.zonesByConst[state.lastOutdoorMap.mapConst]
288:     ) {
289:       destConst = state.lastOutdoorMap.mapConst;
290:     } else if (zone.defaultParent) {
291:       destConst = zone.defaultParent.mapConst;
292:     } else {
293:       destConst = "PALLET_TOWN";
294:     }
295:   }
296:   // Check if we are exiting an elevator that had a floor chosen
297:   if (
298:     ELEVATOR_FLOORS[zone.constName] &&
299:     state.selectedElevatorDest[zone.constName]
300:   ) {
301:     const chosen = state.selectedElevatorDest[zone.constName];
302:     destConst = chosen.destConst;
303:     destWarpIdx = chosen.warpIndex;
304:   }
305:   return { destConst, destWarpIdx };
306: }
