308: function checkWarpAtStep(zone, sx, sy) {
309:   for (let i = 0; i < zone.warps.length; i++) {
310:     const w = zone.warps[i];
311:     if (w.x === sx && w.y === sy) {
312:       return { warp: w, warpIdx: i };
313:     }
314:   }
315:   return null;
316: }
