318: function isWaterTile(zone, tileId) {
319:   return (
320:     (zone.tileset === "OVERWORLD" ||
321:       zone.tileset === "FOREST" ||
322:       zone.tileset === "PLATEAU" ||
323:       zone.tileset === "CAVERN" ||
324:       zone.tileset === "SHIP_PORT") &&
325:     (tileId === 0x14 || tileId === 0x32 || tileId === 0x48)
326:   );
327: }
