329: function attemptStep(dir) {
330:   if (state.dialogue || state.battle) return;
331:   if (state.player.moveAnim) return;
332: 
333:   const zone = state.currentZone;
334:   state.player.dir = dir;
335: 
336:   const dx = dir === "LEFT" ? -1 : dir === "RIGHT" ? 1 : 0;
337:   const dy = dir === "UP" ? -1 : dir === "DOWN" ? 1 : 0;
338:   const targetX = state.player.x + dx;
339:   const targetY = state.player.y + dy;
340: 
341:   // 1. Check if standing on a warp tile at the edge of an indoor room and pressing outward
342:   const standingWarp = checkWarpAtStep(zone, state.player.x, state.player.y);
343:   if (standingWarp) {
344:     const ts = engine.tilesetsByConst[zone.tileset];
345:     const curTile = engine.getCollisionTileAtStep(
346:       zone,
347:       state.player.x,
348:       state.player.y
349:     );
350:     const pushingOut =
351:       (dir === "DOWN" && state.player.y === zone.height * 2 - 1) ||
352:       (dir === "UP" && state.player.y === 0) ||
353:       (dir === "LEFT" && state.player.x === 0) ||
354:       (dir === "RIGHT" && state.player.x === zone.width * 2 - 1) ||
355:       (zone.romId >= 0x25 && dir === "DOWN" && ts.warpSet.has(curTile));
356:     if (pushingOut) {
357:       const { destConst, destWarpIdx } = resolveWarpDestination(
358:         zone,
359:         standingWarp.warp
360:       );
361:       audio.playSfx("warp");
362:       loadZone(destConst, {
363:         warpIndex: destWarpIdx,
364:         fromOutdoorWarpIndex: standingWarp.warpIdx,
365:       });
366:       return;
367:     }
368:   }
369: 
370:   // 2. Check map border connections (North / South / West / East seamless transition!)
371:   const conns = zone.connections || {};
372:   if (targetY < 0 && conns.north) {
373:     const targetZone = engine.zonesByConst[conns.north.targetConst];
374:     if (targetZone) {
375:       const newX = targetX - conns.north.offset * 2;
376:       const newY = targetZone.height * 2 - 1;
377:       if (newX >= 0 && newX < targetZone.width * 2) {
378:         loadZone(targetZone, { x: newX, y: newY, dir: "UP" });
379:         return;
380:       }
381:     }
382:   }
383:   if (targetY >= zone.height * 2 && conns.south) {
384:     const targetZone = engine.zonesByConst[conns.south.targetConst];
385:     if (targetZone) {
386:       const newX = targetX - conns.south.offset * 2;
387:       const newY = 0;
388:       if (newX >= 0 && newX < targetZone.width * 2) {
389:         loadZone(targetZone, { x: newX, y: newY, dir: "DOWN" });
390:         return;
391:       }
392:     }
393:   }
394:   if (targetX < 0 && conns.west) {
395:     const targetZone = engine.zonesByConst[conns.west.targetConst];
396:     if (targetZone) {
397:       const newX = targetZone.width * 2 - 1;
398:       const newY = targetY - conns.west.offset * 2;
399:       if (newY >= 0 && newY < targetZone.height * 2) {
400:         loadZone(targetZone, { x: newX, y: newY, dir: "LEFT" });
401:         return;
402:       }
403:     }
404:   }
405:   if (targetX >= zone.width * 2 && conns.east) {
406:     const targetZone = engine.zonesByConst[conns.east.targetConst];
407:     if (targetZone) {
408:       const newX = 0;
409:       const newY = targetY - conns.east.offset * 2;
410:       if (newY >= 0 && newY < targetZone.height * 2) {
411:         loadZone(targetZone, { x: newX, y: newY, dir: "RIGHT" });
412:         return;
413:       }
414:     }
415:   }
416: 
417:   // Bounds check inside current zone
418:   if (
419:     targetX < 0 ||
420:     targetX >= zone.width * 2 ||
421:     targetY < 0 ||
422:     targetY >= zone.height * 2
423:   ) {
424:     audio.playSfx("bump");
425:     return;
426:   }
427: 
428:   // 3. Check one-way ledge jump!
429:   if (
430:     !state.noClip &&
431:     engine.canJumpLedge(zone, state.player.x, state.player.y, dir)
432:   ) {
433:     const landX = state.player.x + dx * 2;
434:     const landY = state.player.y + dy * 2;
435:     if (
436:       landX >= 0 &&
437:       landX < zone.width * 2 &&
438:       landY >= 0 &&
439:       landY < zone.height * 2
440:     ) {
441:       audio.playSfx("ledge");
442:       startPlayerMove(landX, landY, dir, 260, true);
443:       return;
444:     }
445:   }
446: 
447:   // 4. Check NPC collision
448:   if (!state.noClip) {
449:     for (const npc of state.npcs) {
450:       if (!npc.defaultVisible && !state.showHiddenObjects) continue;
451:       if (npc.collected) continue;
452:       if (npc.x === targetX && npc.y === targetY) {
453:         audio.playSfx("bump");
454:         return;
455:       }
456:     }
457:   }
458: 
459:   // 5. Check tile passability or water surfing
460:   const targetTile = engine.getCollisionTileAtStep(zone, targetX, targetY);
461:   const water = isWaterTile(zone, targetTile);
462:   const passable =
463:     state.noClip ||
464:     engine.isStepPassable(zone, state.player.x, state.player.y, targetX, targetY) ||
465:     (water && (state.player.mode === "surf" || state.autoSurf));
466: 
467:   // Also allow stepping directly onto a warp_event coordinate (e.g. stairs/doors)
468:   const targetWarp = checkWarpAtStep(zone, targetX, targetY);
469: 
470:   if (!passable && !targetWarp) {
471:     audio.playSfx("bump");
472:     return;
473:   }
474: 
475:   if (water && state.player.mode !== "surf") {
476:     state.player.mode = "surf";
477:   } else if (!water && state.player.mode === "surf") {
478:     state.player.mode = "walk";
479:   }
480: 
481:   const dur = state.player.mode === "bike" ? 105 : 165;
482:   startPlayerMove(targetX, targetY, dir, dur, false);
483: }
