485: function startPlayerMove(destX, destY, dir, durationMs, isLedgeJump = false) {
486:   const prevPlayerX = state.player.x;
487:   const prevPlayerY = state.player.y;
488: 
489:   state.player.walking = true;
490:   state.player.stepParity = !state.player.stepParity;
491:   state.player.moveAnim = {
492:     fromX: state.player.x,
493:     fromY: state.player.y,
494:     toX: destX,
495:     toY: destY,
496:     startTime: performance.now(),
497:     duration: durationMs,
498:     isLedgeJump,
499:   };
500: 
501:   // Move Pikachu to Red's previous step
502:   if (state.pikachu.visible) {
503:     const pdx = prevPlayerX - state.pikachu.x;
504:     const pdy = prevPlayerY - state.pikachu.y;
505:     let pdir = dir;
506:     if (Math.abs(pdx) + Math.abs(pdy) > 0) {
507:       if (Math.abs(pdx) >= Math.abs(pdy)) {
508:         pdir = pdx > 0 ? "RIGHT" : "LEFT";
509:       } else {
510:         pdir = pdy > 0 ? "DOWN" : "UP";
511:       }
512:     }
513:     state.pikachu.dir = pdir;
514:     state.pikachu.walking = true;
515:     state.pikachu.stepParity = !state.pikachu.stepParity;
516:     state.pikachu.moveAnim = {
517:       fromX: state.pikachu.x,
518:       fromY: state.pikachu.y,
519:       toX: prevPlayerX,
520:       toY: prevPlayerY,
521:       startTime: performance.now(),
522:       duration: durationMs,
523:     };
524:   }
525: }
