527: function onPlayerStepCompleted() {
528:   const zone = state.currentZone;
529:   const sx = state.player.x;
530:   const sy = state.player.y;
531: 
532:   updateCoordinatesUI();
533: 
534:   // Check if stepped onto a door / staircase warp
535:   const hitWarp = checkWarpAtStep(zone, sx, sy);
536:   if (hitWarp) {
537:     const ts = engine.tilesetsByConst[zone.tileset];
538:     const tileId = engine.getCollisionTileAtStep(zone, sx, sy);
539:     // In Gen 1, doors, stairs, and cave entrances warp immediately on step;
540:     // indoor exit mats at the bottom edge warp either on step or when pressing Down.
541:     const isBottomExitMat =
542:       zone.romId >= 0x25 &&
543:       sy === zone.height * 2 - 1 &&
544:       !ts.doorSet.has(tileId);
545:     if (!isBottomExitMat) {
546:       const { destConst, destWarpIdx } = resolveWarpDestination(
547:         zone,
548:         hitWarp.warp
549:       );
550:       audio.playSfx("warp");
551:       loadZone(destConst, {
552:         warpIndex: destWarpIdx,
553:         fromOutdoorWarpIndex: hitWarp.warpIdx,
554:       });
555:       return;
556:     }
557:   }
558: 
559:   // Check wild Pokémon encounter in tall grass / caves / water
560:   if (state.wildEncountersEnabled) {
561:     const ts = engine.tilesetsByConst[zone.tileset];
562:     const tileId = engine.getCollisionTileAtStep(zone, sx, sy);
563:     const inGrass = tileId === ts.grassTile;
564:     const inCaveOrDungeon =
565:       zone.category === "dungeon" && zone.wild.grassRate > 0;
566:     const onWater = isWaterTile(zone, tileId) && zone.wild.waterRate > 0;
567: 
568:     if (inGrass && zone.wild.grass.length > 0) {
569:       if (Math.random() < 0.14) {
570:         triggerWildEncounter(zone.wild.grass);
571:       }
572:     } else if (onWater && zone.wild.water.length > 0) {
573:       if (Math.random() < 0.1) {
574:         triggerWildEncounter(zone.wild.water);
575:       }
576:     } else if (inCaveOrDungeon && zone.wild.grass.length > 0) {
577:       if (Math.random() < 0.06) {
578:         triggerWildEncounter(zone.wild.grass);
579:       }
580:     }
581:   }
582: }
