584: // Interact with what is in front of Red (A button / Space / Enter)
585: export function interactInFront() {
586:   if (state.battle) return;
587:   if (state.dialogue) {
588:     advanceDialogue();
589:     return;
590:   }
591: 
592:   const zone = state.currentZone;
593:   const dx =
594:     state.player.dir === "LEFT" ? -1 : state.player.dir === "RIGHT" ? 1 : 0;
595:   const dy =
596:     state.player.dir === "UP" ? -1 : state.player.dir === "DOWN" ? 1 : 0;
597:   const fx = state.player.x + dx;
598:   const fy = state.player.y + dy;
599: 
600:   // 1. Check if facing following Pikachu!
601:   if (
602:     state.pikachu.visible &&
603:     state.pikachu.x === fx &&
604:     state.pikachu.y === fy
605:   ) {
606:     openPikachuInteraction();
607:     return;
608:   }
609: 
610:   // 2. Check Elevator control panel
611:   if (ELEVATOR_FLOORS[zone.constName]) {
612:     for (const s of zone.signs) {
613:       if (s.x === fx && s.y === fy) {
614:         openElevatorMenu(zone.constName);
615:         return;
616:       }
617:     }
618:   }
619: 
620:   // 3. Check Signs (bg_events)
621:   for (const s of zone.signs) {
622:     if (s.x === fx && s.y === fy) {
623:       audio.playSfx("blip");
624:       openDialogue("SIGNPOST", s.text);
625:       return;
626:     }
627:   }
628: 
629:   // 4. Check NPCs / Items (including 2 steps away across counter tiles in PokéCenters & Marts!)
630:   const ts = engine.tilesetsByConst[zone.tileset];
631:   const frontTile = engine.getCollisionTileAtStep(zone, fx, fy);
632:   const acrossCounter = ts.counterSet.has(frontTile);
633:   const checkCoords = [[fx, fy]];
634:   if (acrossCounter) {
635:     checkCoords.push([fx + dx, fy + dy]);
636:   }
637: 
638:   for (const [cx, cy] of checkCoords) {
639:     for (const npc of state.npcs) {
640:       if (!npc.defaultVisible && !state.showHiddenObjects) continue;
641:       if (npc.collected) continue;
642:       if (npc.x === cx && npc.y === cy) {
643:         // Turn NPC toward player
644:         const opp = { UP: "DOWN", DOWN: "UP", LEFT: "RIGHT", RIGHT: "LEFT" };
645:         npc.facing = opp[state.player.dir] || "DOWN";
646:         if (npc.kind === "item") {
647:           npc.collected = true;
648:         }
649:         audio.playSfx("blip");
650:         openDialogue(npc.name.replace(/_/g, " "), npc.text);
651:         return;
652:       }
653:     }
654:   }
655: }
