707: export function triggerWildEncounter(poolOrEntry) {
708:   let level = 5;
709:   let species = "PIDGEY";
710:   if (Array.isArray(poolOrEntry) && Array.isArray(poolOrEntry[0])) {
711:     // Gen 1 slot weights: 20%, 20%, 15%, 10%, 10%, 10%, 5%, 5%, 4%, 1%
712:     const pick = poolOrEntry[Math.floor(Math.random() * poolOrEntry.length)];
713:     level = pick[0];
714:     species = pick[1];
715:   } else if (Array.isArray(poolOrEntry)) {
716:     level = poolOrEntry[0];
717:     species = poolOrEntry[1];
718:   }
719:   const maxHp = 14 + level * 3;
720:   state.battle = {
721:     species,
722:     level,
723:     hp: maxHp,
724:     maxHp,
725:     playerHp: 68,
726:     playerMaxHp: 68,
727:     log: `Wild ${species.replace(/_/g, " ")} (Lv.${level}) appeared in ${state.currentZone.displayName}!`,
728:     finished: false,
729:   };
730:   audio.playSfx("thunder");
731:   renderBattleModal();
732: }
