823: function executeBattleAction(action) {
824:   const b = state.battle;
825:   if (!b) return;
826:   if (b.finished || action === "run") {
827:     state.battle = null;
828:     renderBattleModal();
829:     return;
830:   }
831:   if (action === "ball") {
832:     audio.playSfx("warp");
833:     b.hp = 0;
834:     b.finished = true;
835:     b.log = `RED threw a POKé BALL! Gotcha! Wild ${b.species.replace(/_/g, " ")} was caught! (Click RUN/CLOSE to continue)`;
836:     renderBattleModal();
837:     return;
838:   }
839:   const dmg =
840:     action === "thunderbolt"
841:       ? Math.max(8, Math.floor(b.maxHp * 0.65))
842:       : Math.max(5, Math.floor(b.maxHp * 0.42));
843:   audio.playSfx("thunder");
844:   b.hp = Math.max(0, b.hp - dmg);
845:   const moveLabel =
846:     action === "thunderbolt" ? "THUNDERBOLT" : "QUICK ATTACK";
847:   if (b.hp === 0) {
848:     b.finished = true;
849:     b.log = `PIKACHU used ${moveLabel}! Wild ${b.species.replace(/_/g, " ")} fainted! PIKACHU gained ${b.level * 18} EXP!`;
850:   } else {
851:     const counterDmg = Math.max(1, Math.floor(b.level * 0.4));
852:     b.playerHp = Math.max(1, b.playerHp - counterDmg);
853:     b.log = `PIKACHU used ${moveLabel}! Wild ${b.species.replace(/_/g, " ")} used TACKLE (-${counterDmg} HP)!`;
854:   }
855:   renderBattleModal();
856: }
