858: function getFilteredZones() {
859:   const q = state.searchQuery.trim().toLowerCase();
860:   return engine.allZones.filter((z) => {
861:     if (state.categoryFilter === "canonical220" && !z.isCanonical220) {
862:       return false;
863:     }
864:     if (
865:       state.categoryFilter === "town" ||
866:       state.categoryFilter === "route" ||
867:       state.categoryFilter === "indoor" ||
868:       state.categoryFilter === "dungeon"
869:     ) {
870:       if (!z.isCanonical220 || z.category !== state.categoryFilter) return false;
871:     }
872:     if (state.townMapFilterCoords) {
873:       const [tx, ty] = state.townMapFilterCoords;
874:       if (z.townMapX !== tx || z.townMapY !== ty) return false;
875:     }
876:     if (!q) return true;
877:     return (
878:       z.displayName.toLowerCase().includes(q) ||
879:       z.constName.toLowerCase().includes(q) ||
880:       z.headerName.toLowerCase().includes(q) ||
881:       z.regionName.toLowerCase().includes(q) ||
882:       z.tileset.toLowerCase().includes(q) ||
883:       z.romHex.toLowerCase().includes(q) ||
884:       `#${String(z.zoneNumber).padStart(3, "0")}`.includes(q) ||
885:       String(z.zoneNumber) === q
886:     );
887:   });
888: }
