933: function renderKantoTownMap() {
934:   const canvas = document.getElementById("kanto-town-map-canvas");
935:   if (!canvas) return;
936:   const ctx = canvas.getContext("2d");
937:   const W = canvas.width;
938:   const H = canvas.height;
939:   const cellW = W / 16;
940:   const cellH = H / 16;
941: 
942:   ctx.fillStyle = "#162436";
943:   ctx.fillRect(0, 0, W, H);
944: 
945:   // Subtle grid
946:   ctx.strokeStyle = "rgba(148, 163, 184, 0.14)";
947:   ctx.lineWidth = 1;
948:   for (let i = 0; i <= 16; i++) {
949:     ctx.beginPath();
950:     ctx.moveTo(i * cellW, 0);
951:     ctx.lineTo(i * cellW, H);
952:     ctx.stroke();
953:     ctx.beginPath();
954:     ctx.moveTo(0, i * cellH);
955:     ctx.lineTo(W, i * cellH);
956:     ctx.stroke();
957:   }
958: 
959:   // Group zones by (townMapX, townMapY)
960:   const coordMap = {};
961:   for (const z of engine.canonicalZones) {
962:     const key = `${z.townMapX},${z.townMapY}`;
963:     if (!coordMap[key]) coordMap[key] = [];
964:     coordMap[key].push(z);
965:   }
966: 
967:   for (const [key, zonesAtPoint] of Object.entries(coordMap)) {
968:     const [gx, gy] = key.split(",").map(Number);
969:     const hasTown = zonesAtPoint.some((z) => z.category === "town");
970:     const hasDungeon = zonesAtPoint.some((z) => z.category === "dungeon");
971:     const px = gx * cellW;
972:     const py = gy * cellH;
973: 
974:     if (hasTown) {
975:       ctx.fillStyle = "#f59e0b";
976:       ctx.fillRect(px + 2, py + 2, cellW - 4, cellH - 4);
977:     } else if (hasDungeon) {
978:       ctx.fillStyle = "#a855f7";
979:       ctx.fillRect(px + 3, py + 3, cellW - 6, cellH - 6);
980:     } else {
981:       ctx.fillStyle = "#22c55e";
982:       ctx.fillRect(px + 4, py + 4, cellW - 8, cellH - 8);
983:     }
984:   }
985: 
986:   // Highlight active zone's Kanto Town Map coordinate
987:   const cur = state.currentZone;
988:   const cx = cur.townMapX * cellW;
989:   const cy = cur.townMapY * cellH;
990:   ctx.strokeStyle = "#ffffff";
991:   ctx.lineWidth = 2;
992:   ctx.strokeRect(cx + 1, cy + 1, cellW - 2, cellH - 2);
993: }
