59:       this.spriteSheets[k] = {
60:         width: v.width,
61:         height: v.height,
62:         pixels: unpack2Bit(v.data, v.width, v.height),
63:       };
64:     }
65:     this.spriteConstToKey = data.sprites.constToKey;
