67:     this.pikachuFaces = {};
68:     for (const [k, v] of Object.entries(data.sprites.pikachuFaces)) {
69:       this.pikachuFaces[k] = {
70:         width: v.width,
71:         height: v.height,
72:         pixels: unpack2Bit(v.data, v.width, v.height),
73:       };
74:     }
