76:     this.emotes = {};
77:     for (const [k, v] of Object.entries(data.sprites.emotes)) {
78:       this.emotes[k] = {
79:         width: v.width,
80:         height: v.height,
81:         pixels: unpack2Bit(v.data, v.width, v.height),
82:       };
