115:   getPaletteColors(palName, mode = this.paletteMode) {
116:     if (mode === "reference") {
117:       // Exact match to the user's Pallet Town reference image (subtle lavender-white paper bg + crisp 4-shade grays)
118:       if (palName === "PAL_PALLET") {
119:         return [
120:           [252, 246, 255],
121:           [184, 184, 184],
122:           [112, 112, 112],
123:           [20, 20, 20],
124:         ];
125:       }
126:       return [
127:         [250, 250, 250],
128:         [182, 182, 182],
129:         [110, 110, 110],
130:         [20, 20, 20],
131:       ];
132:     }
133:     if (mode === "dmg") {
134:       return [
135:         [224, 248, 208],
136:         [136, 192, 112],
137:         [52, 104, 86],
138:         [8, 24, 32],
139:       ];
140:     }
141:     if (mode === "cgb") {
142:       return (
143:         this.palettes.cgb[palName] ||
144:         this.palettes.cgb.PAL_ROUTE || [
145:           [255, 255, 255],
146:           [140, 230, 80],
147:           [90, 180, 255],
148:           [24, 24, 24],
149:         ]
150:       );
151:     }
152:     // SGB
153:     return (
154:       this.palettes.sgb[palName] ||
155:       this.palettes.sgb.PAL_ROUTE || [
156:         [255, 255, 247],
157:         [189, 214, 156],
158:         [189, 222, 255],
159:         [49, 49, 49],
160:       ]
161:     );
