226:   // Get block ID at (bx, by) in a zone, including connected neighbor zones in the 3-block border!
227:   getBlockAt(zone, bx, by) {
228:     if (bx >= 0 && bx < zone.width && by >= 0 && by < zone.height) {
229:       return zone.blockBytes[by * zone.width + bx];
230:     }
231:     const conns = zone.connections || {};
232:     // Check North connection (by in -3..-1)
233:     if (by < 0 && by >= -3 && conns.north) {
234:       const target = this.zonesByConst[conns.north.targetConst];
235:       if (target) {
236:         const tx = bx - conns.north.offset;
237:         const ty = target.height + by;
238:         if (tx >= 0 && tx < target.width && ty >= 0 && ty < target.height) {
239:           return target.blockBytes[ty * target.width + tx];
240:         }
241:       }
242:     }
243:     // Check South connection (by in height..height+2)
244:     if (by >= zone.height && by < zone.height + 3 && conns.south) {
245:       const target = this.zonesByConst[conns.south.targetConst];
246:       if (target) {
247:         const tx = bx - conns.south.offset;
248:         const ty = by - zone.height;
249:         if (tx >= 0 && tx < target.width && ty >= 0 && ty < target.height) {
250:           return target.blockBytes[ty * target.width + tx];
251:         }
252:       }
253:     }
254:     // Check West connection (bx in -3..-1)
255:     if (bx < 0 && bx >= -3 && conns.west) {
256:       const target = this.zonesByConst[conns.west.targetConst];
257:       if (target) {
258:         const tx = target.width + bx;
259:         const ty = by - conns.west.offset;
260:         if (tx >= 0 && tx < target.width && ty >= 0 && ty < target.height) {
261:           return target.blockBytes[ty * target.width + tx];
262:         }
263:       }
264:     }
265:     // Check East connection (bx in width..width+2)
266:     if (bx >= zone.width && bx < zone.width + 3 && conns.east) {
267:       const target = this.zonesByConst[conns.east.targetConst];
268:       if (target) {
269:         const tx = bx - zone.width;
270:         const ty = by - conns.east.offset;
271:         if (tx >= 0 && tx < target.width && ty >= 0 && ty < target.height) {
272:           return target.blockBytes[ty * target.width + tx];
273:         }
274:       }
275:     }
276:     return zone.borderBlock;
277:   }
