279:   // Get 8x8 tile ID at 8x8 tile coordinate (tx, ty) in zone
280:   getTileIdAt8x8(zone, tx, ty) {
281:     const bx = Math.floor(tx / 4);
282:     const by = Math.floor(ty / 4);
283:     const subX = ((tx % 4) + 4) % 4;
284:     const subY = ((ty % 4) + 4) % 4;
285:     const blockId = this.getBlockAt(zone, bx, by);
286:     const ts = this.tilesetsByConst[zone.tileset];
287:     const bst = this.bstData[ts.bstKey];
288:     const offset = blockId * 16 + subY * 4 + subX;
289:     return offset < bst.length ? bst[offset] : 0;
290:   }
291: 
292:   // In Pokémon Gen I (engine/overworld/player_state.asm _GetTileAndCoordsInFrontOfPlayer),
293:   // each 16x16 step cell (stepX, stepY) uses its lower-left 8x8 tile (stepX*2, stepY*2 + 1)
294:   // for passability, grass, warp tiles, ledges, and pair collisions!
295:   getCollisionTileAtStep(zone, stepX, stepY) {
296:     return this.getTileIdAt8x8(zone, stepX * 2, stepY * 2 + 1);
297:   }
298: 
299:   isStepPassable(zone, fromStepX, fromStepY, toStepX, toStepY) {
300:     const ts = this.tilesetsByConst[zone.tileset];
301:     const targetTile = this.getCollisionTileAtStep(zone, toStepX, toStepY);
302:     if (!ts.passableSet.has(targetTile)) {
303:       return false;
304:     }
305:     // Check elevation pair collisions (data/tilesets/pair_collision_tile_ids.asm)
306:     const fromTile = this.getCollisionTileAtStep(zone, fromStepX, fromStepY);
307:     for (const [tsName, t1, t2] of this.data.tilesets.pairCollisions) {
308:       if (tsName === zone.tileset) {
309:         if (
310:           (fromTile === t1 && targetTile === t2) ||
311:           (fromTile === t2 && targetTile === t1)
312:         ) {
313:           return false;
314:         }
315:       }
316:     }
317:     return true;
318:   }
319: 
320:   // Check if moving in `dir` ("DOWN" | "LEFT" | "RIGHT") from (stepX, stepY) triggers a ledge hop
321:   canJumpLedge(zone, stepX, stepY, dir) {
322:     if (zone.tileset !== "OVERWORLD") return false;
323:     const standTile = this.getCollisionTileAtStep(zone, stepX, stepY);
324:     const dx = dir === "LEFT" ? -1 : dir === "RIGHT" ? 1 : 0;
325:     const dy = dir === "DOWN" ? 1 : 0;
326:     if (dx === 0 && dy === 0) return false;
327:     const frontTile = this.getCollisionTileAtStep(zone, stepX + dx, stepY + dy);
328:     for (const l of this.data.tilesets.ledges) {
329:       if (l.dir === dir && l.standTile === standTile && l.ledgeTile === frontTile) {
330:         return true;
331:       }
332:     }
333:     return false;
334:   }
