336:   // Draw a single 8x8 background tile into an RGBA Uint8ClampedArray buffer
337:   drawTile8x8(
338:     buf,
339:     bufW,
340:     bufH,
341:     destX,
342:     destY,
343:     ts,
344:     tileId,
345:     pal
346:   ) {
347:     const sheet = this.gfxSheets[ts.gfxKey];
348:     if (!sheet) return;
349: 
350:     // Check flower animation on tile $03 (home/vcopy.asm)
351:     if (tileId === 0x03 && ts.anim === "WATER_FLOWER") {
352:       let fIdx = 0;
353:       if (this.animateTiles) {
354:         const c = this.animCounter & 3;
355:         fIdx = c < 2 ? 0 : c === 2 ? 1 : 2;
356:       }
357:       const fPixels = this.flowerFrames[fIdx];
358:       for (let py = 0; py < 8; py++) {
359:         const dy = destY + py;
360:         if (dy < 0 || dy >= bufH) continue;
361:         for (let px = 0; px < 8; px++) {
362:           const dx = destX + px;
363:           if (dx < 0 || dx >= bufW) continue;
364:           const val = fPixels[py * 8 + px];
365:           const c = pal[3 - val];
366:           const off = (dy * bufW + dx) * 4;
367:           buf[off] = c[0];
368:           buf[off + 1] = c[1];
369:           buf[off + 2] = c[2];
370:           buf[off + 3] = 255;
371:         }
372:       }
373:       return;
374:     }
375: 
376:     const tileCol = tileId & 0x0f;
377:     const tileRow = tileId >> 4;
378:     const srcX0 = tileCol * 8;
379:     const srcY0 = tileRow * 8;
380:     if (srcY0 + 8 > sheet.height) return;
381: 
382:     // Check water ripple shift on tile $14
383:     let waterShift = 0;
384:     if (
385:       tileId === 0x14 &&
386:       this.animateTiles &&
387:       (ts.anim === "WATER" || ts.anim === "WATER_FLOWER")
388:     ) {
389:       const c = this.animCounter & 7;
390:       waterShift = c < 4 ? c : 8 - c;
391:     }
392: 
393:     for (let py = 0; py < 8; py++) {
394:       const dy = destY + py;
395:       if (dy < 0 || dy >= bufH) continue;
396:       const sy = srcY0 + py;
397:       for (let px = 0; px < 8; px++) {
398:         const dx = destX + px;
399:         if (dx < 0 || dx >= bufW) continue;
400:         const sx = srcX0 + ((px + waterShift) & 7);
401:         const val = sheet.pixels[sy * sheet.width + sx];
402:         const c = pal[3 - val];
403:         const off = (dy * bufW + dx) * 4;
404:         buf[off] = c[0];
405:         buf[off + 1] = c[1];
406:         buf[off + 2] = c[2];
407:         buf[off + 3] = 255;
408:       }
409:     }
410:   }
