412:   // Draw a 16x16 OAM sprite into RGBA buffer with Game Boy OBP0 transparency
413:   drawSprite16x16(
414:     buf,
415:     bufW,
416:     bufH,
417:     destX,
418:     destY,
419:     spriteKey,
420:     dir = "DOWN",
421:     walking = false,
422:     flipWalk = false,
423:     pal,
424:     underGrass = false,
425:     zone = null,
426:     stepX = 0,
427:     stepY = 0
428:   ) {
429:     const sheet = this.spriteSheets[spriteKey] || this.spriteSheets.red;
430:     if (!sheet) return;
431: 
432:     let frameIdx = 0;
433:     let flipX = false;
434: 
435:     if (sheet.height >= 96) {
436:       if (dir === "DOWN") {
437:         frameIdx = walking ? 3 : 0;
438:         flipX = walking && flipWalk;
439:       } else if (dir === "UP") {
440:         frameIdx = walking ? 4 : 1;
441:         flipX = walking && flipWalk;
442:       } else if (dir === "LEFT") {
443:         frameIdx = walking ? 5 : 2;
444:         flipX = false;
445:       } else if (dir === "RIGHT") {
446:         frameIdx = walking ? 5 : 2;
447:         flipX = true;
448:       }
449:     } else if (sheet.height >= 48) {
450:       if (dir === "DOWN") frameIdx = 0;
451:       else if (dir === "UP") frameIdx = 1;
452:       else if (dir === "LEFT") frameIdx = 2;
453:       else if (dir === "RIGHT") {
454:         frameIdx = 2;
455:         flipX = true;
456:       }
457:     } else {
458:       frameIdx = 0;
459:     }
460: 
461:     const srcY0 = frameIdx * 16;
462:     const accent = this.getSpriteAccentColor(spriteKey, this.paletteMode, pal);
463: 
464:     for (let py = 0; py < 16; py++) {
465:       const dy = destY + py;
466:       if (dy < 0 || dy >= bufH) continue;
467:       for (let px = 0; px < 16; px++) {
468:         const dx = destX + px;
469:         if (dx < 0 || dx >= bufW) continue;
470:         const sx = flipX ? 15 - px : px;
471:         const val = sheet.pixels[(srcY0 + py) * sheet.width + sx];
472:         // In Game Boy OAM (rOBP0): val 3 is transparent, val 2 is white (pal[0]), val 1 is accent/gray (pal[1]), val 0 is black (pal[3])
473:         if (val === 3) continue;
474:         // Authentic tall-grass masking on bottom half of sprite
475:         if (underGrass && py >= 8 && ((px + py) & 1) === 0) continue;
476: 
477:         const c = val === 2 ? pal[0] : val === 1 ? accent : pal[3];
478:         const off = (dy * bufW + dx) * 4;
479:         buf[off] = c[0];
480:         buf[off + 1] = c[1];
481:         buf[off + 2] = c[2];
482:         buf[off + 3] = 255;
483:       }
484:     }
485:   }
