487:   // Render an entire zone segment (width*32 x height*32 pixels) onto a Canvas
488:   renderFullZone(
489:     canvas,
490:     zone,
491:     options = {}
492:   ) {
493:     const {
494:       showBorder = false,
495:       showEntities = true,
496:       showWarps = false,
497:       showGrid = false,
498:       showHiddenObjects = false,
499:       playerState = null,
500:       pikachuState = null,
501:       npcStates = null,
502:     } = options;
503: 
504:     const borderBlocks = showBorder ? 1 : 0;
505:     const totalBlocksW = zone.width + borderBlocks * 2;
506:     const totalBlocksH = zone.height + borderBlocks * 2;
507:     const pxW = totalBlocksW * 32;
508:     const pxH = totalBlocksH * 32;
509: 
510:     if (canvas.width !== pxW || canvas.height !== pxH) {
511:       canvas.width = pxW;
512:       canvas.height = pxH;
513:     }
514: 
515:     const ctx = canvas.getContext("2d");
516:     const imgData = ctx.createImageData(pxW, pxH);
517:     const buf = imgData.data;
518: 
519:     const ts = this.tilesetsByConst[zone.tileset];
520:     const bst = this.bstData[ts.bstKey];
521:     const pal = this.getPaletteColors(zone.palette);
522: 
523:     for (let by = -borderBlocks; by < zone.height + borderBlocks; by++) {
524:       for (let bx = -borderBlocks; bx < zone.width + borderBlocks; bx++) {
525:         const blockId = this.getBlockAt(zone, bx, by);
526:         const destBlockX = (bx + borderBlocks) * 32;
527:         const destBlockY = (by + borderBlocks) * 32;
528:         for (let ty = 0; ty < 4; ty++) {
529:           for (let tx = 0; tx < 4; tx++) {
530:             const tileId = bst[blockId * 16 + ty * 4 + tx] || 0;
531:             this.drawTile8x8(
532:               buf,
533:               pxW,
534:               pxH,
535:               destBlockX + tx * 8,
536:               destBlockY + ty * 8,
537:               ts,
538:               tileId,
539:               pal
540:             );
541:           }
542:         }
543:       }
544:     }
545: 
546:     const originPx = borderBlocks * 32;
547: 
548:     if (showEntities) {
549:       // Draw zone objects (NPCs, items, trainers)
550:       const list = npcStates || zone.objects;
551:       for (const obj of list) {
552:         if (!obj.defaultVisible && !showHiddenObjects) continue;
553:         if (obj.collected) continue;
554:         const sprKey = this.spriteConstToKey[obj.sprite] || "red";
555:         const ox = originPx + Math.round((obj.renderX ?? obj.x) * 16);
556:         const oy = originPx + Math.round((obj.renderY ?? obj.y) * 16) - 4;
557:         const dir =
558:           obj.facing ||
559:           (obj.dir === "UP" || obj.dir === "DOWN" || obj.dir === "LEFT" || obj.dir === "RIGHT"
560:             ? obj.dir
561:             : "DOWN");
562:         this.drawSprite16x16(
563:           buf,
564:           pxW,
565:           pxH,
566:           ox,
567:           oy,
568:           sprKey,
569:           dir,
570:           Boolean(obj.isWalking),
571:           Boolean(obj.stepParity),
572:           pal
573:         );
574:       }
575: 
576:       // Draw following Pikachu & Player if in this zone
577:       if (pikachuState && pikachuState.visible) {
578:         const px = originPx + Math.round(pikachuState.renderX * 16);
579:         const py = originPx + Math.round(pikachuState.renderY * 16) - 4;
580:         const onGrass =
581:           this.getCollisionTileAtStep(
582:             zone,
583:             Math.round(pikachuState.renderX),
584:             Math.round(pikachuState.renderY)
585:           ) === ts.grassTile;
586:         this.drawSprite16x16(
587:           buf,
588:           pxW,
589:           pxH,
590:           px,
591:           py,
592:           "pikachu",
593:           pikachuState.dir,
594:           pikachuState.walking,
595:           pikachuState.stepParity,
596:           pal,
597:           onGrass
598:         );
599:       }
600: 
601:       if (playerState) {
602:         const rx = originPx + Math.round(playerState.renderX * 16);
603:         const ry = originPx + Math.round(playerState.renderY * 16) - 4;
604:         const onGrass =
605:           this.getCollisionTileAtStep(
606:             zone,
607:             Math.round(playerState.renderX),
608:             Math.round(playerState.renderY)
609:           ) === ts.grassTile;
610:         const sprKey =
611:           playerState.mode === "bike"
612:             ? "red_bike"
613:             : playerState.mode === "surf"
614:             ? "surfing_pikachu"
615:             : "red";
616:         this.drawSprite16x16(
617:           buf,
618:           pxW,
619:           pxH,
620:           rx,
621:           ry,
622:           sprKey,
623:           playerState.dir,
624:           playerState.walking,
625:           playerState.stepParity,
626:           pal,
627:           onGrass
628:         );
629:       }
630:     }
631: 
632:     ctx.putImageData(imgData, 0, 0);
633: 
634:     // Optional overlays (Collision grid, Warp markers, Sign markers, Connection borders)
635:     if (showBorder && borderBlocks > 0) {
636:       ctx.save();
637:       ctx.strokeStyle = "rgba(255, 204, 0, 0.85)";
638:       ctx.lineWidth = 1.5;
639:       ctx.setLineDash([4, 3]);
640:       ctx.strokeRect(originPx + 0.5, originPx + 0.5, zone.width * 32 - 1, zone.height * 32 - 1);
641:       ctx.restore();
642:     }
643: 
644:     if (showGrid) {
645:       ctx.save();
646:       ctx.font = "bold 7px monospace";
647:       for (let sy = 0; sy < zone.height * 2; sy++) {
648:         for (let sx = 0; sx < zone.width * 2; sx++) {
649:           const tileId = this.getCollisionTileAtStep(zone, sx, sy);
650:           const passable = ts.passableSet.has(tileId);
651:           const isGrass = tileId === ts.grassTile;
652:           const gx = originPx + sx * 16;
653:           const gy = originPx + sy * 16;
654:           if (!passable) {
655:             ctx.fillStyle = "rgba(220, 38, 38, 0.26)";
656:             ctx.fillRect(gx, gy, 16, 16);
657:           } else if (isGrass) {
658:             ctx.fillStyle = "rgba(34, 197, 94, 0.28)";
